t3template.addControl({ id: 'grain', label: 'Grain', type: 'slider', min: 0, max: 0.4, step: 0.01, default: 0.08, panel: 'Finish' });
t3template.addControl({ id: 'footer', label: 'Footer', type: 'text', placeholder: 'Footer text', default: 'Sonoma Spring 2026', panel: 'Finish' });
t3template.addControl({ id: 'numbers', label: 'Slide No.', type: 'toggle', default: true, panel: 'Finish' });
t3template.addImageStage('grain', ({ context, width, height, random }, c) => {
  if (c.grain <= 0) return;
  const rnd = random('grain');
  const px = context.getImageData(0, 0, width, height);
  const amount = c.grain * 255;
  for (let i = 0; i < px.data.length; i += 4) {
    const n = (rnd() - 0.5) * amount;
    px.data[i] += n;
    px.data[i + 1] += n;
    px.data[i + 2] += n;
  }
  context.putImageData(px, 0, 0);
});
t3template.addImageStage('footer', ({ context, width, height, index, count }, c) => {
  context.fillStyle = getComputedStyle(document.documentElement).getPropertyValue('--muted-foreground').trim();
  context.font = `500 ${Math.round(width * 0.016)}px sans-serif`;
  context.textBaseline = 'middle';
  const y = height - height * 0.05;
  if (c.footer) {
    context.textAlign = 'left';
    context.fillText(c.footer, width * 0.073, y);
  }
  if (c.numbers) {
    context.textAlign = 'right';
    context.fillText(`${index + 1} / ${count}`, width - width * 0.073, y);
  }
});
t3template.addToolbarButton('Grain Off', (t) => t.setValues({ controls: { grain: 0 } }), { shortcut: 'shift+g', title: 'Set grain to 0' });
